use serde::Serialize;use serde_json::Value;
#[derive(Serialize)]struct PromptReply{text:String,html:Option<String>}
#[tauri::command]async fn run_prompt(base_url:String,model:String,api_key:String,prompt:String,temperature:f32)->Result<PromptReply,String>{if api_key.trim().is_empty(){return Err("Add your provider API key in Model settings first.".into())}if model.trim().is_empty(){return Err("Enter a model ID in Model settings.".into())}let base=base_url.trim().trim_end_matches("/");if !(base.starts_with("https://")||base.starts_with("http://127.0.0.1")||base.starts_with("http://localhost")){return Err("Use HTTPS for remote providers or localhost for local models.".into())}let system="You are an expert web designer and developer. For website or interface requests, return a complete standalone HTML document with embedded CSS and JavaScript. Return only HTML, no markdown fences. For other requests, answer helpfully.";let response=reqwest::Client::new().post(format!("{}/chat/completions",base)).bearer_auth(api_key).json(&serde_json::json!({"model":model,"temperature":temperature,"messages":[{"role":"system","content":system},{"role":"user","content":prompt}]})).send().await.map_err(|e|format!("Could not reach provider: {e}"))?;let status=response.status();let body:Value=response.json().await.map_err(|e|format!("Provider returned an unreadable response: {e}"))?;if !status.is_success(){let msg=body.pointer("/error/message").and_then(Value::as_str).unwrap_or("Provider request failed.");return Err(format!("Provider returned HTTP {}: {}",status.as_u16(),msg))}let text=body.pointer("/choices/0/message/content").and_then(Value::as_str).ok_or_else(||"Provider response did not contain a message. Check model and endpoint.".to_string())?.to_string();let cleaned=text.trim().to_string();let html=if cleaned.to_lowercase().starts_with("<!doctype html")||cleaned.to_lowercase().starts_with("<html"){Some(cleaned)}else{None};Ok(PromptReply{text,html})}
pub fn run(){tauri::Builder::default().invoke_handler(tauri::generate_handler![run_prompt]).run(tauri::generate_context!()).expect("error while running AI Studio Desktop");}